var o=[{title:`O que as máquinas oferecem`,text:`As máquinas de seleção por pino costumam guiar o trajeto do movimento e podem reduzir a necessidade de equilíbrio. Isso pode ajudar um iniciante a concentrar-se em empurrar ou puxar com controlo. Algumas máquinas ajustam-se melhor a certos tamanhos de corpo do que outras, por isso um trajeto guiado não é confortável para toda a gente.`},{title:`Preparar o posto`,text:`Ajuste a altura do assento, o apoio das costas e as almofadas para que a articulação que trabalha fique razoavelmente alinhada com as peças móveis e consiga alcançar a pega sem esforço. Faça uma série de teste leve antes de escolher a carga de trabalho. Mantenha as mãos longe das pilhas de pesos, dos pontos de entalamento e dos braços móveis e baixe a resistência devagar. Os ginásios têm equipamento diferente, por isso verifique a máquina ou o posto de polia exatos que tem e mude para uma opção com pesos livres, banda ou peso do corpo se não conseguir ajustar a máquina para ficar confortável.`},{title:`Como as polias diferem`,text:`Os sistemas de polia permitem puxar de várias direções, com tensão ao longo da linha do cabo. Funcionam bem para remadas, puxadas, press e exercícios antirrotação. A resistência da polia não é exatamente constante em todos os ângulos da articulação, porque a alavanca e a direção do cabo mudam ao longo do movimento.`},{title:`Comparar ferramentas`,text:`Os pesos livres pedem-lhe que estabilize mais a carga por si, enquanto as máquinas podem tornar alguns exercícios mais fáceis de aprender ou de carregar com precisão. Ambos podem desenvolver força e tamanho muscular quando o esforço e a progressão são adequados. Uma máquina não protege automaticamente uma articulação lesionada ou dolorosa. Se os sintomas persistirem, consulte um médico ou fisioterapeuta.`}];var s=[{label:`Mayo Clinic: pesos livres versus máquinas de musculação`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Mayo Clinic: técnica de treino com pesos (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var i={sections:o,sources:s};export{i as default,o as sections,s as sources};